import React, { useCallback, useRef, useState } from 'react';
import { HostEvent } from '@thoughtspot/visual-embed-sdk';
import { SearchEmbed, SpotterEmbed } from '@thoughtspot/visual-embed-sdk/react';
import { THOUGHTSPOT_MODEL_ID, VIEWPORT_LESS_TOP_HEADER } from '../config/thoughtspot';
import { useTier } from '../config/TierContext';
import { formatThoughtSpotEmbedError } from '../utils/thoughtspotErrors';

type TabId = 'stella' | 'explore';

const DARK = '#1C1C1E';
const DARK_2 = '#2C2C2E';
const BRAND_PINK = '#FF2D55';

function TabCard({
  active,
  title,
  subtitle,
  onClick,
}: {
  active: boolean;
  title: string;
  subtitle: string;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      style={{
        flex: '1 1 160px',
        minWidth: 140,
        textAlign: 'left',
        padding: '1.25rem 1.35rem',
        borderRadius: 12,
        border: active ? `1px solid ${BRAND_PINK}` : '1px solid rgba(255,255,255,0.12)',
        backgroundColor: active ? BRAND_PINK : 'rgba(255,255,255,0.06)',
        color: active ? '#ffffff' : 'rgba(255,255,255,0.85)',
        cursor: 'pointer',
        transition: 'background-color 0.15s ease, border-color 0.15s ease',
      }}
    >
      <div style={{ fontWeight: 600, fontSize: 15, marginBottom: 4, letterSpacing: '-0.02em' }}>{title}</div>
      <div
        style={{
          fontSize: 13,
          fontWeight: 400,
          color: active ? 'rgba(255,255,255,0.8)' : 'rgba(255,255,255,0.45)',
        }}
      >
        {subtitle}
      </div>
    </button>
  );
}

function StellaUpgrade({ onUpgrade }: { onUpgrade: () => void }) {
  return (
    <div
      style={{
        backgroundColor: '#fff',
        borderRadius: 16,
        border: '1px solid #F3E6EA',
        padding: '3rem 2rem',
        textAlign: 'center',
        maxWidth: 480,
        margin: '2rem auto',
        boxShadow: '0 2px 24px rgba(0,0,0,0.10)',
      }}
    >
      <div style={{ fontSize: 32, marginBottom: 12 }}>✦</div>
      <h2 style={{ fontSize: 20, fontWeight: 700, color: '#1C1C1E', margin: '0 0 8px', letterSpacing: '-0.03em' }}>Meet Stella</h2>
      <p style={{ fontSize: 14, color: '#6B7280', lineHeight: 1.6, margin: '0 0 1.25rem' }}>
        Ask questions in plain English about your retail data. Upgrade to Pro to unlock Stella, your AI fashion analyst.
      </p>
      <button
        type="button"
        onClick={onUpgrade}
        style={{
          backgroundColor: BRAND_PINK,
          color: '#fff',
          border: 'none',
          padding: '10px 28px',
          borderRadius: 24,
          fontSize: 14,
          fontWeight: 600,
          cursor: 'pointer',
          letterSpacing: '-0.01em',
        }}
      >
        Upgrade to Pro
      </button>
    </div>
  );
}

export default function Analytics() {
  const [tab, setTab] = useState<TabId>('stella');
  const [selectedPrompt, setSelectedPrompt] = useState<string | undefined>(undefined);
  const { hiddenActions, disabledActions, spotterEnabled, setTier } = useTier();
  const spotterRef = useRef<any>(null);
  const searchRef = useRef<any>(null);

  const onError = useCallback((err: { data?: { errorMessage?: string }; message?: string }) => {
    console.error('[ThoughtSpot Analytics]', formatThoughtSpotEmbedError(err), err);
  }, []);

      const handleRefresh = () => {
    try {
      if (tab === 'stella') spotterRef.current?.trigger(HostEvent.Reload);
      else searchRef.current?.trigger(HostEvent.Reload);
    } catch (e) {
      console.warn('Reload trigger', e);
    }
  };

  const section =
    tab === 'stella'
      ? { title: 'Stella', subtitle: 'Ask anything about your retail data in plain English.' }
      : { title: 'Explore', subtitle: 'Build your own analysis from the data source.' };

  return (
    <div
      style={{
        minHeight: VIEWPORT_LESS_TOP_HEADER,
        display: 'flex',
        flexDirection: 'column',
        backgroundColor: DARK,
        overflowX: 'hidden',
        overflowY: 'auto',
      }}
    >
      <div
        style={{
          position: 'sticky',
          top: 0,
          zIndex: 30,
          flexShrink: 0,
          borderBottom: '1px solid rgba(255,255,255,0.08)',
        }}
      >
        {/* Dark title banner */}
        <div style={{ backgroundColor: DARK, padding: '1.75rem 2.5rem 1.25rem' }}>
          <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', flexWrap: 'wrap', gap: 16 }}>
            <div>
              <div style={{ fontSize: 10, fontWeight: 600, letterSpacing: '0.12em', textTransform: 'uppercase', color: BRAND_PINK, marginBottom: 6 }}>
                Maison
              </div>
              <h1 style={{ fontSize: 28, fontWeight: 700, color: '#ffffff', margin: 0, letterSpacing: '-0.03em' }}>
                Explore & Ask Stella
              </h1>
              <p style={{ fontSize: 14, color: 'rgba(255,255,255,0.55)', margin: '6px 0 0', maxWidth: 520 }}>
                Ask your AI fashion analyst, or build your own analysis with Search.
              </p>
            </div>
            <div style={{ display: 'flex', gap: 10, alignItems: 'center', flexShrink: 0 }}>
              <button
                type="button"
                onClick={handleRefresh}
                style={{
                  padding: '9px 18px',
                  borderRadius: 24,
                  border: '1px solid rgba(255,255,255,0.2)',
                  background: 'rgba(255,255,255,0.08)',
                  color: '#ffffff',
                  fontSize: 14,
                  fontWeight: 500,
                  cursor: 'pointer',
                  letterSpacing: '-0.01em',
                }}
              >
                Refresh
              </button>
            </div>
          </div>
        </div>

        {/* Tab cards */}
        <div style={{ backgroundColor: DARK_2, padding: '0.85rem 2.5rem' }}>
          <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap', alignItems: 'stretch' }}>
            <TabCard
              active={tab === 'stella'}
              title="✦ Stella"
              subtitle="Ask questions in plain English"
              onClick={() => { setTab('stella'); }}
            />
            <TabCard
              active={tab === 'explore'}
              title="Explore"
              subtitle="Build your own analysis"
              onClick={() => { setTab('explore'); }}
            />
          </div>
        </div>
      </div>

      <div
        style={{
          padding: '1rem 2.5rem 1.5rem',
          flex: '1 1 auto',
          minHeight: 320,
          display: 'flex',
          flexDirection: 'column',
          backgroundColor: DARK,
        }}
      >
        <h2 style={{ fontSize: 18, fontWeight: 600, color: '#ffffff', margin: '0 0 4px', flexShrink: 0, letterSpacing: '-0.02em' }}>
          {section.title}
        </h2>
        <p style={{ fontSize: 14, color: 'rgba(255,255,255,0.5)', margin: '0 0 1rem', flexShrink: 0 }}>
          {section.subtitle}
        </p>

        {tab === 'stella' && !spotterEnabled ? (
          <StellaUpgrade onUpgrade={() => setTier('Pro')} />
        ) : (
          <div
            style={{
              flex: '1 1 auto',
              minHeight: 480,
              backgroundColor: '#ffffff',
              borderRadius: 16,
              border: 'none',
              overflow: 'hidden',
              display: 'flex',
              flexDirection: 'column',
              boxShadow: '0 2px 32px rgba(0,0,0,0.5)',
            }}
          >
            {tab === 'stella' && spotterEnabled && (
              <SpotterEmbed
                key={selectedPrompt ?? 'stella-default'}
                ref={spotterRef}
                worksheetId={THOUGHTSPOT_MODEL_ID}
                onError={onError}
                hideSampleQuestions={!selectedPrompt}
                {...(selectedPrompt ? { searchOptions: { searchQuery: selectedPrompt } } : {})}
                style={{ width: '100%', height: '100%', flex: 1, minHeight: 400, border: 'none' }}
              />
            )}
            {tab === 'explore' && (
              <SearchEmbed
                ref={searchRef}
                dataSource={THOUGHTSPOT_MODEL_ID}
                hiddenActions={hiddenActions}
                disabledActions={disabledActions}
                onError={onError}
                style={{ width: '100%', height: '100%', flex: 1, minHeight: 400, border: 'none' }}
              />
            )}
          </div>
        )}
      </div>
    </div>
  );
}
